module cla_16bit(
    input [15:0] a,
    input [15:0] b,
    input cin,
    output [15:0] sum,
    output cout,
    output p_group,
    output g_group
);
    wire [3:0] p_4bit; 
    wire [3:0] g_4bit; 
    wire [3:0] c_16bit; 


    cla_4bit cla_block0(
        .a(a[3:0]),
        .b(b[3:0]),
        .cin(cin),
        .sum(sum[3:0]),
        .cout(c_16bit[0]),
        .p_group(p_4bit[0]),
        .g_group(g_4bit[0])
    );


    cla_4bit cla_block1(
        .a(a[7:4]),
        .b(b[7:4]),
        .cin(c_16bit[0]),
        .sum(sum[7:4]),
        .cout(c_16bit[1]),
        .p_group(p_4bit[1]),
        .g_group(g_4bit[1])
    );


    cla_4bit cla_block2(
        .a(a[11:8]),
        .b(b[11:8]),
        .cin(c_16bit[1]),
        .sum(sum[11:8]),
        .cout(c_16bit[2]),
        .p_group(p_4bit[2]),
        .g_group(g_4bit[2])
    );


    cla_4bit cla_block3(
        .a(a[15:12]),
        .b(b[15:12]),
        .cin(c_16bit[2]),
        .sum(sum[15:12]),
        .cout(c_16bit[3]),
        .p_group(p_4bit[3]),
        .g_group(g_4bit[3])
    );


    assign p_group = p_4bit[0] & p_4bit[1] & p_4bit[2] & p_4bit[3];
    assign g_group = g_4bit[3] | 
                    (g_4bit[2] & p_4bit[3]) | 
                    (g_4bit[1] & p_4bit[3] & p_4bit[2]) | 
                    (g_4bit[0] & p_4bit[3] & p_4bit[2] & p_4bit[1]);


    assign cout = c_16bit[3];
endmodule

module cla_4bit(
    input [3:0] a,
    input [3:0] b,
    input cin,
    output [3:0] sum,
    output cout,
    output p_group,
    output g_group
);
    wire [3:0] p; 
    wire [3:0] g; 
    wire [4:0] c; 


    assign p = a ^ b;
    assign g = a & b;


    assign c[0] = cin;
    assign c[1] = g[0] | (p[0] & c[0]);
    assign c[2] = g[1] | (p[1] & c[1]);
    assign c[3] = g[2] | (p[2] & c[2]);
    assign c[4] = g[3] | (p[3] & c[3]);


    assign sum = p ^ {c[3:0]};


    assign p_group = p[0] & p[1] & p[2] & p[3];
    assign g_group = g[3] | (g[2] & p[3]) | (g[1] & p[3] & p[2]) | (g[0] & p[3] & p[2] & p[1]);


    assign cout = c[4];
endmodule

module parallel2serial (
    input wire clk,
    input wire rst_n,
    input wire [3:0]d,
    output wire valid_out,
    output wire dout
);

reg [3:0] data;
reg [1:0] cnt;
reg valid;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        data <= 4'b0;
        cnt <= 2'b0;
        valid <= 1'b0;
    end else begin
        if (cnt == 2'd3) begin
            data <= d;
            cnt <= 2'b0;
            valid <= 1'b1;
        end else begin
            data <= {data[2:0], data[3]};
            cnt <= cnt + 1'b1;
            valid <= 1'b0;
        end
    end
end

assign dout = data[3];
assign valid_out = valid;

endmodule

module multi_8bit (
    input [7:0] A,
    input [7:0] B,
    output reg [15:0] product
);
	reg [15:0] product_reg;
	integer i;
	always@(*) begin
		product_reg = 16'd0;
		for(i=0;i<8;i=i+1) begin
			if(B[i])
				product_reg = product_reg+(A<<i);
		end
	end

	assign product = product_reg;

endmodule

module signal_generator (
    input clk,
    input rst_n,
    output reg [4:0] wave
);

reg [1:0] state;

always @(posedge clk or negedge rst_n) begin
    if (~rst_n) begin
        state <= 2'b00;
        wave <= 5'b0;
    end else begin
        case(state)
            2'b00: begin
                if (wave == 5'b11111) begin
                    state <= 2'b01;
                end else begin
                    wave <= wave + 1;
                end
            end
            2'b01: begin
                if (wave == 5'b00000) begin
                    state <= 2'b00;
                end else begin
                    wave <= wave - 1;
                end
            end
        endcase
    end
end
endmodule

