module calendar (
    input CLK,
    input RST,
    output reg [5:0] Hours,
    output reg [5:0] Mins,
    output reg [5:0] Secs
);

always @(posedge CLK or posedge RST) begin
    if (RST) begin
        Secs <= 0;
        Mins <= 0;
        Hours <= 0;
    end else begin
        if (Secs == 59) begin
            Secs <= 0;
            if (Mins == 59) begin
                Mins <= 0;
                if (Hours == 23) begin
                    Hours <= 0;
                end else begin
                    Hours <= Hours + 1;
                end
            end else begin
                Mins <= Mins + 1;
            end
        end else begin
            Secs <= Secs + 1;
        end
    end
end

endmodule

module multi_pipe_4bit #(
    parameter size = 4,
    parameter N = 2 * size
) (
    input 						clk,
    input 						rst_n,
    input	[size-1:0]			mul_a,
    input	[size-1:0]			mul_b,
    output	reg	[size*2-1:0]	mul_out
);

reg [size*2-1:0] sum_tmp1, sum_tmp2;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        sum_tmp1 <= 0;
        sum_tmp2 <= 0;
    end else begin
        sum_tmp1 <= (mul_b[0] ? mul_a : 0) + (mul_b[1] ? mul_a << 1 : 0);
        sum_tmp2 <= (mul_b[2] ? mul_a << 2 : 0) + (mul_b[3] ? mul_a << 3 : 0);
    end
end

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        mul_out <= 0;
    end else begin
        mul_out <= sum_tmp1 + sum_tmp2;
    end
end

endmodule

module right_shifter (
    input clk,
    output reg [7:0] q,
    input d
);
    initial begin
        q = 8'b0;
    end

    always @(posedge clk) begin
        q <= (q >> 1);
        q[7] <= d;
    end
endmodule

module multi_16bit (
    input clk,
    input rst_n,
    input start,
    input [15:0] ain,
    input [15:0] bin,
    output [31:0] yout,
    output done
);

reg [31:0] product;
reg done_reg;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        product <= 0;
        done_reg <= 0;
    end else if (start) begin
        product <= ain * bin;
        done_reg <= 1;
    end else begin
        done_reg <= 0;
    end
end

assign yout = product;
assign done = done_reg;

endmodule

module synchronizer (
    input 				clk_a,
    input 				clk_b,
    input 				arstn,
    input				brstn,
    input		[3:0]	data_in,
    input               data_en,
    output reg  [3:0] 	dataout
);

reg [3:0] data_reg;
always @(posedge clk_a or negedge arstn) begin
    if (~arstn) begin
        data_reg <= 4'd0;
    end else begin
        data_reg <= data_in;
    end
end

reg en_data_reg;
always @(posedge clk_a or negedge arstn) begin
    if (~arstn) begin
        en_data_reg <= 1'd0;
    end else begin
        en_data_reg <= data_en;
    end
end

reg en_clap_one;
reg en_clap_two;
always @(posedge clk_b or negedge brstn) begin
    if (~brstn) begin
        en_clap_one <= 1'd0;
        en_clap_two <= 1'd0;
    end else begin
        en_clap_one <= en_data_reg;
        en_clap_two <= en_clap_one;
    end
end

always @(posedge clk_b or negedge brstn) begin
    if (~brstn) begin
        dataout <= 4'd0;
    end else begin
        if (en_clap_two) begin
            dataout <= data_reg;
        end else begin
            dataout <= dataout;
        end
    end
end
endmodule

module multi_pipe_8bit #(
    parameter size = 8
) (
    input clk,
    input rst_n,
    input [size-1:0] mul_a,
    input [size-1:0] mul_b,
    input mul_en_in,
    output reg mul_en_out,
    output reg [size*2-1:0] mul_out
);

reg [3:0] mul_en_out_reg;
reg [7:0] mul_a_reg, mul_b_reg;
reg [15:0] temp[0:7];
reg [15:0] sum[0:3];
reg [15:0] mul_out_reg;
always@(posedge clk or negedge rst_n)begin
	if(!rst_n)begin
		mul_en_out_reg <= 4'd0;
	end
	else begin
		mul_en_out_reg <= {mul_en_out_reg[2:0],mul_en_in};
	end
end
assign mul_en_out = mul_en_out_reg[3];
always@(posedge clk or negedge rst_n)begin
	if(!rst_n)begin
		mul_a_reg <= 8'd0;
		mul_b_reg <= 8'd0;
	end
	else begin
		if(mul_en_in==1'b1)begin
			mul_a_reg <= mul_a;
			mul_b_reg <= mul_b;
		end
		else begin
			mul_a_reg <= 8'd0;
			mul_b_reg <= 8'd0;
		end
	end
end
always@(*)begin
	temp[0] = mul_b_reg[0]?{8'd0,mul_a_reg}:16'd0;
	temp[1] = mul_b_reg[1]?{7'd0,mul_a_reg,1'd0}:16'd0;
	temp[2] = mul_b_reg[2]?{6'd0,mul_a_reg,2'd0}:16'd0;
	temp[3] = mul_b_reg[3]?{5'd0,mul_a_reg,3'd0}:16'd0;
	temp[4] = mul_b_reg[4]?{4'd0,mul_a_reg,4'd0}:16'd0;
	temp[5] = mul_b_reg[5]?{3'd0,mul_a_reg,5'd0}:16'd0;
	temp[6] = mul_b_reg[6]?{2'd0,mul_a_reg,6'd0}:16'd0;
	temp[7] = mul_b_reg[7]?{1'd0,mul_a_reg,7'd0}:16'd0;
end
always@(posedge clk or negedge rst_n)begin
	if(!rst_n)begin
		sum[0] <= 16'd0;
		sum[1] <= 16'd0;
		sum[2] <= 16'd0;
		sum[3] <= 16'd0;
	end
	else begin
		sum[0] <= temp[0]+temp[1];
		sum[1] <= temp[2]+temp[3];
		sum[2] <= temp[4]+temp[5];
		sum[3] <= temp[6]+temp[7];
	end
end
always@(posedge clk or negedge rst_n)begin
	if(!rst_n)begin
		mul_out_reg <= 16'd0;
	end
	else begin
		mul_out_reg <= sum[0]+sum[1]+sum[2]+sum[3];
	end
end
assign mul_out = mul_en_out?mul_out_reg:16'd0;
endmodule

module accu (
    input               clk,
    input               rst_n,
    input       [7:0]   data_in,
    input               valid_in,
    output  reg         valid_out,
    output  reg [9:0]   data_out
);

reg [9:0] accum;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        accum <= 0;
        valid_out <= 0;
    end else begin
        if (valid_in) begin
            accum <= accum + {data_in, 2'b0};
            if (accum >= 10'd1000) begin
                data_out <= accum;
                valid_out <= 1;
                accum <= 0;
            end else begin
                valid_out <= 0;
            end
        end else begin
            valid_out <= 0;
        end
    end
end

endmodule

module serial2parallel (
    input clk,
    input rst_n,
    input din_serial,
    input din_valid,
    output reg [7:0]dout_parallel,
    output reg dout_valid
);

reg [3:0] cnt;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        cnt <= 4'b0;
        dout_parallel <= 8'b0;
        dout_valid <= 1'b0;
    end else begin
        if (din_valid) begin
            dout_parallel[7-cnt] <= din_serial;
            cnt <= cnt + 1'b1;
            if (cnt == 4'b1111) begin
                dout_valid <= 1'b1;
            end else begin
                dout_valid <= 1'b0;
            end
            if (cnt == 4'b1111) begin
                cnt <= 4'b0;
            end
        end
    end
end

endmodule

module traffic_light #(
    parameter idle = 2'd0,
    parameter s1_red = 2'd1,
    parameter s2_yellow = 2'd2,
    parameter s3_green = 2'd3
) (
    input rst_n,
    input clk,
    input pass_request,
    output wire[7:0]clock,
    output reg red,
    output reg yellow,
    output reg green
);

reg [7:0] cnt;
reg [1:0] state;
reg p_red, p_yellow, p_green;
always@(posedge clk or negedge rst_n) begin
	if(!rst_n) begin
		state <= idle;
		p_red <= 0;
		p_yellow <= 0;
		p_green <= 0;
	end
	else begin
		case(state)
			idle: begin
				p_red <= 0;
				p_yellow <= 0;
				p_green <= 0;
				state <= s1_red;
			end
			s1_red: begin
				p_red <= 1;
				p_yellow <= 0;
				p_green <= 0;
				if(cnt == 3) begin
					state <= s3_green;
				end
				else begin
					state <= s1_red;
				end
			end
			s2_yellow: begin
				p_red <= 0;
				p_yellow <= 1;
				p_green <= 0;
				if(cnt == 3) begin
					state <= s1_red;
				end
				else begin
					state <= s2_yellow;
				end
			end
			s3_green: begin
				p_red <= 0;
				p_yellow <= 0;
				p_green <= 1;
				if(cnt == 3) begin
					state <= s2_yellow;
				end
				else begin
					state <= s3_green;
				end
			end
		endcase
	end
end
always@(posedge clk or negedge rst_n) begin
	if(!rst_n) begin
		cnt <= 10;
	end
	else begin
		if(pass_request && green && (cnt > 10)) begin
			cnt <= 10;
		end
		else if(!green && p_green) begin
			cnt <= 60;
		end
		else if(!yellow && p_yellow) begin
			cnt <= 5;
		end
		else if(!red && p_red) begin
			cnt <= 10;
		end
		else begin
			cnt <= cnt - 1;
		end
	end
end
assign clock = cnt;
always@(posedge clk or negedge rst_n) begin
	if(!rst_n) begin
		red <= 0;
		yellow <= 0;
		green <= 0;
	end
	else begin
		red <= p_red;
		yellow <= p_yellow;
		green <= p_green;
	end
end
endmodule

module adder_pipe_64bit #(
    parameter DATA_WIDTH = 64,
    parameter STG_WIDTH = 16
) (
    input clk,
    input rst_n,
    input i_en,
    input [DATA_WIDTH-1:0] adda,
    input [DATA_WIDTH-1:0] addb,
    output [DATA_WIDTH:0] result,
    output reg o_en
);

reg [DATA_WIDTH-1:0] adda_reg, addb_reg;
reg [DATA_WIDTH:0] sum;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        adda_reg <= 0;
        addb_reg <= 0;
        sum <= 0;
        o_en <= 0;
    end else begin
        if (i_en) begin
            adda_reg <= adda;
            addb_reg <= addb;
            sum <= {1'b0, adda} + {1'b0, addb};
            o_en <= 1;
        end else begin
            o_en <= 0;
        end
    end
end

assign result = sum;

endmodule

module freq_div (
    input CLK_in,
    output reg CLK_50,
    output reg CLK_10,
    output reg CLK_1,
    input RST
);

    reg [3:0] cnt_10;
    reg [6:0] cnt_100;

    always @(posedge CLK_in or posedge RST) begin
        if (RST) begin
            cnt_10 <= 4'b0;
            cnt_100 <= 7'b0;
            CLK_50 <= 1'b0;
            CLK_10 <= 1'b0;
            CLK_1 <= 1'b0;
        end else begin
            cnt_10 <= cnt_10 + 1'b1;
            cnt_100 <= cnt_100 + 1'b1;
            CLK_50 <= ~CLK_50;
            if (cnt_10 == 4'd9) begin
                CLK_10 <= ~CLK_10;
                cnt_10 <= 4'b0;
            end
            if (cnt_100 == 7'd99) begin
                CLK_1 <= ~CLK_1;
                cnt_100 <= 7'b0;
            end
        end
    end

endmodule

module div_8bit (
    input wire clk,
    input wire rst,
    input wire [7:0] dividend,
    input wire [7:0] divisor,
    input wire sign,
    input wire opn_valid,
    output reg res_valid,
    input wire res_ready,
    output wire [15:0] result
);

reg [7:0] dividend_reg;
reg [7:0] divisor_reg;
reg [15:0] result_reg;
reg [3:0] cnt;
reg [3:0] start_cnt;
reg [15:0] SR;
reg [7:0] NEG_DIVISOR;
reg [7:0] temp_result;
reg [7:0] selected_result;
reg [7:0] CARRY_OUT;
reg [7:0] SHIFT_REGISTER;

always @(posedge clk or posedge rst) begin
    if (rst) begin
        cnt <= 0;
        start_cnt <= 0;
    end else if (opn_valid && !res_valid) begin
        dividend_reg <= dividend;
        divisor_reg <= divisor;
        result_reg <= {8'h00, dividend};
        cnt <= 1;
        start_cnt <= 1;
    end else if (start_cnt) begin
        if (cnt[3]) begin
            cnt <= 0;
            start_cnt <= 0;
            result_reg <= {SR[15:8], SR[7:0]};
        end else begin
            cnt <= cnt + 1;
            case ({CARRY_OUT})
                8'd0: begin
                    selected_result = SR[15:8];
                    CARRY_OUT = 0;
                end
                default: begin
                    selected_result = SR[15:8] - 1;
                    CARRY_OUT = 1;
                end
            endcase
            SHIFT_REGISTER = {selected_result, SR[7:1]};
            SR <= {SHIFT_REGISTER, SR[0]};
        end
    end
end

assign res_valid = (rst | cnt == 8) ? 1'b0 :
                   (res_valid & res_ready) ? 1'b0 : res_valid;
assign result = result_reg;
endmodule

module pulse_detect #(
    parameter s0 = 2'b00,
    parameter s1 = 2'b01,
    parameter s2 = 2'b10,
    parameter s3 = 2'b11
) (
    input clk,
    input rst_n,
    input data_in,
    output reg data_out
);


	reg [1:0] state, next_state;

	always @(posedge clk or negedge rst_n) begin
		if(~rst_n) begin
			state <= s0;
		end
		else begin
			state <= next_state;
		end
	end

	always @(*) begin
		case(state)
			s0 : begin
				if(data_in == 0)	next_state = s1;
				else 				next_state = s0;
			end

			s1 : begin
				if(data_in == 0)	next_state = s1;
				else 				next_state = s2;
			end

			s2 : begin
				if(data_in == 0)	next_state = s3;
				else 				next_state = s0;
			end

			default : next_state = s0;
		endcase

	end

	always @(*) begin
		if((state == s2) && (data_in == 0))	begin
			data_out = 1;
		end
		else								data_out = 0;

	end

endmodule

module asyn_fifo #(
    parameter	WIDTH = 8,
    parameter 	DEPTH = 16,
    parameter ADDR_WIDTH = $clog2(DEPTH)
) (
    input 					wclk,
    input 					rclk,
    input 					wrstn,
    input					rrstn,
    input 					winc,
    input 			 		rinc,
    input 		[WIDTH-1:0]	wdata,
    output wire				wfull,
    output wire				rempty,
    output wire [WIDTH-1:0]	rdata
);

reg [WIDTH-1:0] ram_mem[DEPTH-1:0];
reg [WIDTH-1:0] rdata_reg;
reg [ADDR_WIDTH:0] waddr_bin;
reg [ADDR_WIDTH:0] raddr_bin;
reg [ADDR_WIDTH:0] wptr;
reg [ADDR_WIDTH:0] rptr;
reg [ADDR_WIDTH:0] wptr_buff;
reg [ADDR_WIDTH:0] rptr_buff;
reg [ADDR_WIDTH:0] wptr_syn;
reg [ADDR_WIDTH:0] rptr_syn;
reg wen;
reg ren;

function [ADDR_WIDTH:0] bin_to_gray(input [ADDR_WIDTH:0] bin);
begin
    bin_to_gray = {bin[ADDR_WIDTH], bin[ADDR_WIDTH-1:0] ^ bin[ADDR_WIDTH:1]};
end
endfunction

function [ADDR_WIDTH:0] gray_to_bin(input [ADDR_WIDTH:0] gray);
begin
    gray_to_bin[ADDR_WIDTH] = gray[ADDR_WIDTH];
    gray_to_bin[ADDR_WIDTH-1:0] = gray[ADDR_WIDTH:1] ^ gray[ADDR_WIDTH-1:0];
end
endfunction

reg [WIDTH-1:0] RAM_MEM [0:DEPTH-1];

always @(posedge wclk) begin
    if (wen)
        RAM_MEM[waddr_bin[ADDR_WIDTH-1:0]] <= wdata;
end

always @(posedge rclk) begin
    if (ren)
        rdata_reg <= RAM_MEM[raddr_bin[ADDR_WIDTH-1:0]];
end

always @(posedge wclk or negedge wrstn) begin
    if (!wrstn) begin
        waddr_bin <= 0;
    end else if (winc && !wfull) begin
        waddr_bin <= waddr_bin + 1;
    end
end

always @(posedge rclk or negedge rrstn) begin
    if (!rrstn) begin
        raddr_bin <= 0;
    end else if (rinc && !rempty) begin
        raddr_bin <= raddr_bin + 1;
    end
end

always @(posedge wclk or negedge wrstn) begin
    if (!wrstn) begin
        wptr <= 0;
    end else begin
        wptr <= bin_to_gray(waddr_bin);
    end
end

always @(posedge rclk or negedge rrstn) begin
    if (!rrstn) begin
        rptr <= 0;
    end else begin
        rptr <= bin_to_gray(raddr_bin);
    end
end

always @(posedge wclk or negedge wrstn) begin
    if (!wrstn) begin
        wptr_buff <= 0;
    end else begin
        wptr_buff <= wptr;
    end
end

always @(posedge rclk or negedge rrstn) begin
    if (!rrstn) begin
        rptr_buff <= 0;
    end else begin
        rptr_buff <= rptr;
    end
end

always @(posedge wclk or negedge wrstn) begin
    if (!wrstn) begin
        wptr_syn <= 0;
    end else begin
        wptr_syn <= wptr_buff;
    end
end

always @(posedge rclk or negedge rrstn) begin
    if (!rrstn) begin
        rptr_syn <= 0;
    end else begin
        rptr_syn <= rptr_buff;
    end
end

always @(*) begin
    wen = winc & !wfull;
end

always @(*) begin
    ren = rinc & !rempty;
end

assign wfull = (wptr == {~rptr_syn[ADDR_WIDTH:ADDR_WIDTH-1], rptr_syn[ADDR_WIDTH-2:0]});
assign rempty = (rptr == wptr_syn);
assign rdata = rdata_reg;

endmodule

module dual_port_RAM #(parameter DEPTH = 16,  parameter WIDTH = 8)
(
	 input wclk	,
	 input wenc	,
	 input [$clog2(DEPTH)-1:0] waddr  ,
	 input [WIDTH-1:0] wdata ,
	 input rclk	,
	 input renc	,
	 input [$clog2(DEPTH)-1:0] raddr ,
	 output reg [WIDTH-1:0] rdata 		
);

reg [WIDTH-1:0] RAM_MEM [0:DEPTH-1];

always @(posedge wclk) begin
	if(wenc)
		RAM_MEM[waddr] <= wdata;
end 

always @(posedge rclk) begin
	if(renc)
		rdata <= RAM_MEM[raddr];
end 

endmodule

module alu #(
    parameter ADD = 6'b100000,
    parameter ADDU = 6'b100001,
    parameter SUB = 6'b100010,
    parameter SUBU = 6'b100011,
    parameter AND = 6'b100100,
    parameter OR = 6'b100101,
    parameter XOR = 6'b100110,
    parameter NOR = 6'b100111,
    parameter SLT = 6'b101010,
    parameter SLTU = 6'b101011,
    parameter SLL = 6'b000000,
    parameter SRL = 6'b000010,
    parameter SRA = 6'b000011,
    parameter SLLV = 6'b000100,
    parameter SRLV = 6'b000110,
    parameter SRAV = 6'b000111,
    parameter LUI = 6'b001111
) (
    input [31:0] a,
    input [31:0] b,
    input [5:0] aluc,
    output [31:0] r,
    output zero,
    output reg carry,
    output negative,
    output reg overflow,
    output flag
);

    wire [31:0] a_signed, b_signed;
    assign a_signed = {a[31], a};
    assign b_signed = {b[31], b};

    reg [31:0] res;
    reg [31:0] temp_res;
    reg [31:0] temp_a, temp_b;
    reg [4:0] count;

    always @(*) begin
        case (aluc)
            ADD: begin
                {carry, res} = a_signed + b_signed;
                overflow = carry ^ res[31];
            end
            ADDU: begin
                temp_res = a + b;
                carry = temp_res[32] ^ temp_res[31];
                res = temp_res[31:0];
            end
            SUB: begin
                {carry, res} = a_signed - b_signed;
                overflow = carry ^ res[31];
            end
            SUBU: begin
                temp_res = a - b;
                carry = temp_res[32] ^ temp_res[31];
                res = temp_res[31:0];
            end
            AND: res = a & b;
            OR: res = a | b;
            XOR: res = a ^ b;
            NOR: res = ~(a | b);
            SLT: begin
                temp_res = a_signed < b_signed ? 32'hFFFFFFFF : 32'h00000000;
                res = temp_res;
            end
            SLTU: begin
                temp_res = a < b ? 32'hFFFFFFFF : 32'h00000000;
                res = temp_res;
            end
            SLL: begin
                temp_a = a;
                temp_b = b[5:0];
                for (count = 0; count < temp_b; count = count + 1) begin
                    temp_a = {temp_a[30:0], 1'b0};
                end
                res = temp_a;
            end
            SRL: begin
                temp_a = a;
                temp_b = b[5:0];
                for (count = 0; count < temp_b; count = count + 1) begin
                    temp_a = {1'b0, temp_a[31:1]};
                end
                res = temp_a;
            end
            SRA: begin
                temp_a = a;
                temp_b = b[5:0];
                for (count = 0; count < temp_b; count = count + 1) begin
                    temp_a = {{temp_a[31]}, temp_a[31:1]};
                end
                res = temp_a;
            end
            SLLV: begin
                temp_a = a;
                temp_b = b[5:0];
                for (count = 0; count < temp_b; count = count + 1) begin
                    temp_a = {temp_a[30:0], 1'b0};
                end
                res = temp_a;
            end
            SRLV: begin
                temp_a = a;
                temp_b = b[5:0];
                for (count = 0; count < temp_b; count = count + 1) begin
                    temp_a = {1'b0, temp_a[31:1]};
                end
                res = temp_a;
            end
            SRAV: begin
                temp_a = a;
                temp_b = b[5:0];
                for (count = 0; count < temp_b; count = count + 1) begin
                    temp_a = {{temp_a[31]}, temp_a[31:1]};
                end
                res = temp_a;
            end
            LUI: res = {b, 16'b0};
            default: res = 32'h00000000;
        endcase
    end

    assign r = res;
    assign zero = res == 32'h00000000 ? 1'b1 : 1'b0;
    assign negative = res[31];
    assign flag = aluc == SLT || aluc == SLTU ? 1'b1 : 1'b0;

endmodule
